class PaymentResponseModel {final String? snapToken,redirectUrl,qrisUrl,paymentUrl;final String orderNumber;final int? totalAmount; PaymentResponseModel({this.snapToken,this.redirectUrl,this.qrisUrl,this.paymentUrl,required this.orderNumber,this.totalAmount}); factory PaymentResponseModel.fromJson(Map<String,dynamic> j)=>PaymentResponseModel(snapToken:j['snap_token']?.toString(),redirectUrl:j['redirect_url']?.toString(),qrisUrl:j['qris_url']?.toString(),paymentUrl:j['payment_url']?.toString(),orderNumber:(j['order_number']??'-').toString(),totalAmount:(j['total_amount'] as num?)?.toInt());}
